import React, { useEffect, useState } from 'react';
import SalesDailyReportForm from './SalesDailyReportForm';

const outcomeLabels = {
  registered: 'Registered',
  ready_to_register: 'Ready to register',
  appointment: 'Appointment',
  undecided: 'Undecided',
  promised: 'Promised',
  declined: 'Not interested',
};

export default function SalesReportsPage({ reports: initialReports = [], onSubmitted }) {
  const [showForm, setShowForm] = useState(false);
  const [reports, setReports] = useState(initialReports);

  useEffect(() => {
    setReports(initialReports);
  }, [initialReports]);

  const handleSubmitted = (report) => {
    setReports((current) => [report, ...current]);
    onSubmitted?.(report);
  };

  return (
    <section className="sales-reports-page" id="sales-reports-page">
      <div className="sales-page-hero">
        <div>
          <p className="leave-kicker">FIELD OPERATIONS</p>
          <h2>Sales Reports</h2>
          <p className="leave-muted">Record every client visit, follow-up, registration, and document received today.</p>
        </div>
        <button type="button" className="leave-primary-button" onClick={() => setShowForm((current) => !current)}>
          {showForm ? 'Close report' : 'Add New'}
        </button>
      </div>

      {showForm && <SalesDailyReportForm onSubmitted={handleSubmitted} />}

      <div className="sales-day-summary">
        <div><strong>{reports.length}</strong><span>Clients recorded today</span></div>
        <div><strong>{reports.filter((report) => report.customer_type === 'agent').length}</strong><span>M-Pesa Agents</span></div>
        <div><strong>{reports.filter((report) => report.customer_type === 'sub_agent').length}</strong><span>M-Pesa Sub-Agents</span></div>
        <div><strong>{reports.filter((report) => report.outcome === 'registered').length}</strong><span>Registrations</span></div>
      </div>

      <section className="sales-visit-list" aria-labelledby="sales-visit-list-title">
        <div className="leave-section-heading"><div><p className="leave-kicker">TODAY'S VISITS</p><h3 id="sales-visit-list-title">Client visit records</h3></div><span className="section-meta">{reports.length} recorded</span></div>
        {reports.length === 0 ? (
          <div className="sales-empty-state"><strong>No client visits recorded yet.</strong><span>Press Add New to record the first visit for today.</span></div>
        ) : (
          <div className="sales-visit-table-wrap"><table className="leave-table"><thead><tr><th>Client</th><th>Type</th><th>Status</th><th>Location</th><th>Documents</th></tr></thead><tbody>{reports.map((report) => {
            const documents = Object.values(report.documents || {}).filter(Boolean).length;
            return <tr key={report.id || `${report.agent_name}-${report.date_visited}`}><td><strong>{report.business_owner_name || report.agent_name}</strong><small>{report.agent_number || report.store_number || 'No client number'}</small></td><td>{report.customer_type === 'sub_agent' ? 'M-Pesa Sub-Agent' : 'M-Pesa Agent'}</td><td><span className="sales-outcome">{outcomeLabels[report.outcome] || report.outcome}</span></td><td>{report.business_location || '-'}</td><td>{documents ? `${documents} submitted` : 'Pending'}</td></tr>;
          })}</tbody></table></div>
        )}
      </section>
    </section>
  );
}
